seed += productSeed;
seed += "INSERT INTO invoices VALUES(6,5,'2025-01',5);";
seed += "INSERT INTO videos VALUES(6,12,'Practice together',2400); INSERT INTO watch_events VALUES(25,6,6,'2025-01-10 15:00:00',1080),(26,7,6,'2025-01-11 11:00:00',1080);";
seed += "INSERT INTO social_events VALUES(22,'u',1,'view','2025-01-01 11:20:00','2025-01-01 11:20:01');";
groups.splice(0,groups.length,'SQL foundations','Filtering & unique values','Calculations & data quality','Joins & aggregation','Dates, strings & subqueries','Window functions','Advanced product analysis');
lessons.forEach(l=>{const old=l.group;l.dataset='shop';l.difficulty=old<2?'Beginner':old<4?'Intermediate':'Advanced';l.group=old===0?0:old===1?1:old===2?2:old===3?3:5;});
[17,18,20,26].forEach(i=>lessons[i].group=4);
[19,27,28,29].forEach(i=>lessons[i].group=6);
function advanced(title,group,dataset,concept,example,tasks,hints,trap,prereq=[]){lesson(title,group,concept,example,tasks,hints,trap);const l=lessons.at(-1);l.dataset=dataset;l.difficulty=group<2?'Beginner':group<5?'Intermediate':'Advanced';l.prereq=prereq;}
advanced('MIN, MAX & the grain of a result',0,'stream','MIN and MAX summarize the smallest and largest values. The grain describes what one output row means. Adding GROUP BY changes that grain from one overall row to one row per group.','SELECT MIN(watch_seconds) AS shortest_watch,\nMAX(watch_seconds) AS longest_watch FROM watch_events;',[
 ['Return shortest_watch and longest_watch: minimum and maximum watch_seconds across all watch events.','SELECT MIN(watch_seconds) AS shortest_watch,MAX(watch_seconds) AS longest_watch FROM watch_events'],
 ['Return video_id and longest_watch: maximum watch_seconds for each video that has events.','SELECT video_id,MAX(watch_seconds) AS longest_watch FROM watch_events GROUP BY video_id']
],['Decide whether the task wants one overall row or one row per video.','Use MIN and MAX; put video_id in GROUP BY for the second task.'],'A maximum value alone does not identify every other column from that row.',[9]);
advanced('NOT IN and the NULL trap',1,'stream','NOT reverses true and false, but unknown stays unknown. If a NOT IN list contains NULL, a nonmatching comparison can become unknown and disappear from WHERE. Prefer NOT EXISTS for nullable relationships.','SELECT id FROM viewers\nWHERE id NOT IN (SELECT referred_by FROM viewers\n                 WHERE referred_by IS NOT NULL);',[
 ['Return id for viewers who have not referred anyone. A referred_by value identifies the referrer, and NULL means no referrer.','SELECT v.id FROM viewers v WHERE NOT EXISTS(SELECT 1 FROM viewers r WHERE r.referred_by=v.id)'],
 ['Return id and country for viewers outside US and GB.','SELECT id,country FROM viewers WHERE country NOT IN(\'US\',\'GB\')']
],['The nullable referred_by column makes a bare NOT IN unsafe.','Correlate the inner referred_by to the outer viewer id with NOT EXISTS.'],'Filtering NULL out of the subquery or using NOT EXISTS avoids the unknown-value trap.',[7,18]);
advanced('Ratios, ROUND & NULLIF',2,'ai','A rate is numerator divided by denominator. Use a real number (100.0) to avoid integer division. NULLIF(x,0) turns a zero denominator into NULL; ROUND controls displayed precision. Preserve that NULL instead of calling an undefined rate zero.','SELECT account_id,ROUND(100.0 * SUM(CASE WHEN status=\'success\'\nTHEN 1 ELSE 0 END)/NULLIF(COUNT(*),0),2) AS success_pct\nFROM ai_requests GROUP BY account_id;',[
 ['Return account_id and success_pct (0–100, rounded to 2 decimals) for accounts with requests.','SELECT account_id,ROUND(100.0*SUM(CASE WHEN status=\'success\' THEN 1 ELSE 0 END)/NULLIF(COUNT(*),0),2) AS success_pct FROM ai_requests GROUP BY account_id'],
 ['Return id and success_pct for every account, including accounts with no requests (NULL rate). Round to 2 decimals.','SELECT a.id,ROUND(100.0*SUM(CASE WHEN r.status=\'success\' THEN 1 ELSE 0 END)/NULLIF(COUNT(r.id),0),2) AS success_pct FROM ai_accounts a LEFT JOIN ai_requests r ON r.account_id=a.id GROUP BY a.id']
],['Count requests, not placeholder rows produced by LEFT JOIN.','Use 100.0 * successes / NULLIF(COUNT(r.id),0) for all accounts.'],'COUNT(*) in a LEFT JOIN makes an account with no requests appear to have one request.',[13,15]);
advanced('Clean strings & cast values',4,'social','TRIM removes outside spaces, LOWER normalizes case, SUBSTR extracts a portion, and CAST makes a conversion explicit. Keep NULL visible when the source is missing. SQLite uses SUBSTR; many engines also provide SUBSTRING.','SELECT id,LOWER(TRIM(email)) AS clean_email FROM members;',[
 ['Return id and clean_email for every member: trim outside spaces and lowercase the email; preserve NULL.','SELECT id,LOWER(TRIM(email)) AS clean_email FROM members'],
 ['Return id and email_domain: lowercase, trim, and take the email text after @. Preserve NULL.','SELECT id,SUBSTR(LOWER(TRIM(email)),INSTR(TRIM(email),\'@\')+1) AS email_domain FROM members']
],['Nest LOWER around TRIM.','INSTR finds @; SUBSTR starts one character after it.'],'Normalizing email is useful for analysis, but changing a real identity field needs business rules.',[7]);
advanced('Self-joins & referral relationships',3,'social','A self-join uses the same table in two roles. Use different aliases for the member and referrer. LEFT JOIN retains members who were not referred.','SELECT m.id AS member_id,r.id AS referrer_id\nFROM members m LEFT JOIN members r ON r.id=m.referrer_id;',[
 ['Return member_id and referrer_id for every member, keeping NULL when no referrer exists.','SELECT m.id AS member_id,r.id AS referrer_id FROM members m LEFT JOIN members r ON r.id=m.referrer_id'],
 ['Return member_id and referrer_country for members with a referrer, taking the country from the referrer row.','SELECT m.id AS member_id,r.country AS referrer_country FROM members m JOIN members r ON r.id=m.referrer_id']
],['The same table can appear twice with different aliases.','Join referrer.id to member.referrer_id.'],'The member’s country and the referrer’s country are different attributes.',[14]);
advanced('CROSS JOIN & a complete date grid',3,'stream','CROSS JOIN creates every pair of rows. It is useful for a deliberate date × entity grid, but careless use multiplies data. A short recursive date spine supplies missing days.','WITH RECURSIVE days(day) AS (\n SELECT \'2025-01-01\' UNION ALL\n SELECT date(day,\'+1 day\') FROM days WHERE day<\'2025-01-03\'\n) SELECT day,v.id AS viewer_id FROM days CROSS JOIN viewers v;',[
 ['Return day and viewer_id for every day from 2025-01-01 through 2025-01-03 inclusive and every viewer, including pre-signup combinations.','WITH RECURSIVE days(day) AS(SELECT \'2025-01-01\' UNION ALL SELECT date(day,\'+1 day\') FROM days WHERE day<\'2025-01-03\') SELECT day,v.id AS viewer_id FROM days CROSS JOIN viewers v'],
 ['Return day and viewer_id for the same date range, keeping only combinations on or after that viewer\'s signup_at.','WITH RECURSIVE days(day) AS(SELECT \'2025-01-01\' UNION ALL SELECT date(day,\'+1 day\') FROM days WHERE day<\'2025-01-03\') SELECT day,v.id AS viewer_id FROM days CROSS JOIN viewers v WHERE day>=v.signup_at']
],['Generate one row per date, then pair it with each viewer.','Filter day >= signup_at after creating the grid for the second task.'],'The expected grid size is dates × viewers before the signup filter.',[27]);
advanced('FULL OUTER JOIN & unmatched records',3,'ai','FULL OUTER JOIN keeps unmatched rows from both sides. Reconciliation often needs this to find missing records. This SQLite version supports FULL OUTER JOIN; older SQLite versions did not.','SELECT i.id AS invoice_id,p.id AS payment_id\nFROM invoices i FULL OUTER JOIN payments p ON p.invoice_id=i.id;',[
 ['Return invoice_id and payment_id for every invoice/payment match, retaining unmatched rows on either side. Keep split payments as separate rows.','SELECT i.id AS invoice_id,p.id AS payment_id FROM invoices i FULL OUTER JOIN payments p ON p.invoice_id=i.id'],
 ['Return payment_id for payments whose invoice_id has no matching invoice, including NULL invoice_id.','SELECT p.id AS payment_id FROM payments p LEFT JOIN invoices i ON i.id=p.invoice_id WHERE i.id IS NULL']
],['Use FULL OUTER JOIN for retaining both sides.','A missing invoice match has i.id IS NULL.'],'Split payments make one invoice match more than one payment.',[15]);
advanced('ON versus WHERE in a LEFT JOIN',3,'ai','ON decides which right-side rows may match. WHERE filters the joined output. Put a success condition in ON when you need to keep accounts with no successful requests.','SELECT a.id,COUNT(r.id) AS successful_requests\nFROM ai_accounts a LEFT JOIN ai_requests r\nON r.account_id=a.id AND r.status=\'success\' GROUP BY a.id;',[
 ['Return id and successful_requests for every account, including zero successful requests.','SELECT a.id,COUNT(r.id) AS successful_requests FROM ai_accounts a LEFT JOIN ai_requests r ON r.account_id=a.id AND r.status=\'success\' GROUP BY a.id'],
 ['Return id and error_requests for every account, including zero failed requests (status = error).','SELECT a.id,COUNT(r.id) AS error_requests FROM ai_accounts a LEFT JOIN ai_requests r ON r.account_id=a.id AND r.status=\'error\' GROUP BY a.id']
],['Keep accounts on the left and status in the ON condition.','COUNT(r.id), not COUNT(*), represents matching requests.'],'A WHERE r.status filter discards unmatched accounts and changes the result.',[15]);
advanced('INTERSECT & EXCEPT',3,'stream','INTERSECT keeps distinct rows appearing in both results. EXCEPT keeps distinct rows from the first result that are absent from the second. Column positions and types should align.','SELECT viewer_id FROM watch_events WHERE video_id=1\nINTERSECT SELECT viewer_id FROM watch_events WHERE video_id=2;',[
 ['Return viewer_id for viewers who watched both video 1 and video 2. Each viewer appears once.','SELECT viewer_id FROM watch_events WHERE video_id=1 INTERSECT SELECT viewer_id FROM watch_events WHERE video_id=2'],
 ['Return viewer_id for viewers who watched video 1 but never video 2. Each viewer appears once.','SELECT viewer_id FROM watch_events WHERE video_id=1 EXCEPT SELECT viewer_id FROM watch_events WHERE video_id=2']
],['Build one set of viewer ids for each video.','INTERSECT is both; EXCEPT is first minus second.'],'UNION means either set, which answers a different question.',[19]);
advanced('Date boundaries & monthly buckets',4,'stream','For timestamps, use a half-open interval: >= start and < next boundary. This includes every time on the last day without guessing the final second. SQLite uses strftime/date; PostgreSQL uses DATE_TRUNC and INTERVAL. All teaching timestamps are UTC.','SELECT id,watched_at FROM watch_events\nWHERE watched_at >= \'2025-01-01\' AND watched_at < \'2025-02-01\';',[
 ['Return id and watched_at for January 2025 watch events, including the full final day and excluding February.','SELECT id,watched_at FROM watch_events WHERE watched_at>=\'2025-01-01\' AND watched_at<\'2025-02-01\''],
 ['Return month (YYYY-MM) and active_viewers (distinct viewers) across all watch events by month.','SELECT strftime(\'%Y-%m\',watched_at) AS month,COUNT(DISTINCT viewer_id) AS active_viewers FROM watch_events GROUP BY month']
],['End at the first instant of the next month, using <.','Format the timestamp to year-month before grouping.'],'BETWEEN with an end date at midnight can omit that date’s later events.',[26]);
advanced('LEAD & the next event',5,'stream','LEAD looks forward within a partition. Use it to see the next event or compute a gap. The last row has no next event and returns NULL. Deterministic ordering needs a tie-breaker.','SELECT id,viewer_id,LEAD(watched_at) OVER(\n PARTITION BY viewer_id ORDER BY watched_at,id\n) AS next_watch_at FROM watch_events;',[
 ['Return id, viewer_id and next_watch_at for each viewer\'s next watch event, ordering each viewer by watched_at then id.','SELECT id,viewer_id,LEAD(watched_at) OVER(PARTITION BY viewer_id ORDER BY watched_at,id) AS next_watch_at FROM watch_events'],
 ['Return id and seconds_to_next: next watched_at minus current watched_at in seconds per viewer, ordered by watched_at then id. Last events get NULL.','SELECT id,unixepoch(LEAD(watched_at) OVER(PARTITION BY viewer_id ORDER BY watched_at,id))-unixepoch(watched_at) AS seconds_to_next FROM watch_events']
],['Put LEAD(watched_at) inside a viewer partition.','unixepoch converts a timestamp to integer seconds for subtraction.'],'Using global rather than per-viewer order compares unrelated people.',[24]);
advanced('FIRST_VALUE, LAST_VALUE & frames',5,'stream','FIRST_VALUE and LAST_VALUE read endpoints of a window frame. LAST_VALUE with the default ordered frame often returns the current row. Use UNBOUNDED FOLLOWING to reach the final row in the partition.','SELECT id,viewer_id,LAST_VALUE(video_id) OVER(\n PARTITION BY viewer_id ORDER BY watched_at,id\n ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING\n) AS last_video FROM watch_events;',[
 ['Return id, viewer_id and last_video for each viewer\'s final watched video, ordered within viewer by watched_at then id. Repeat that final video on every viewer row.','SELECT id,viewer_id,LAST_VALUE(video_id) OVER(PARTITION BY viewer_id ORDER BY watched_at,id ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) AS last_video FROM watch_events'],
 ['Return id, viewer_id and first_video for each viewer\'s first watched video, ordered within viewer by watched_at then id.','SELECT id,viewer_id,FIRST_VALUE(video_id) OVER(PARTITION BY viewer_id ORDER BY watched_at,id) AS first_video FROM watch_events']
],['For LAST_VALUE the frame must include future rows.','Use ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING.'],'The default frame is not always the entire partition.',[23]);
advanced('Rolling averages & missing dates',5,'stream','A rolling average smooths variation. ROWS counts rows, not calendar days. When dates are missing, a three-row average differs from a three-day average. Fill missing days with zero only if the business definition says absence means no activity.','SELECT day,watch_minutes,ROUND(AVG(watch_minutes) OVER(\n ORDER BY day ROWS BETWEEN 2 PRECEDING AND CURRENT ROW\n),2) AS rolling_avg FROM daily_metrics;',[
 ['Return day, watch_minutes and rolling_avg (2 decimals) for the current and previous 2 observed rows in daily_metrics, sorted by day. This task intentionally uses rows, not calendar days.','SELECT day,watch_minutes,ROUND(AVG(watch_minutes) OVER(ORDER BY day ROWS BETWEEN 2 PRECEDING AND CURRENT ROW),2) AS rolling_avg FROM daily_metrics ORDER BY day',true],
 ['Return day, watch_minutes and rolling_avg (2 decimals) for every day Jan 1–7 2025, treating absent daily_metrics days as zero. Average current and previous 2 calendar days; early windows use available days. Sort by day.','WITH RECURSIVE days(day) AS(SELECT \'2025-01-01\' UNION ALL SELECT date(day,\'+1 day\') FROM days WHERE day<\'2025-01-07\'), complete AS(SELECT d.day,COALESCE(m.watch_minutes,0) AS watch_minutes FROM days d LEFT JOIN daily_metrics m ON m.day=d.day) SELECT day,watch_minutes,ROUND(AVG(watch_minutes) OVER(ORDER BY day ROWS BETWEEN 2 PRECEDING AND CURRENT ROW),2) AS rolling_avg FROM complete ORDER BY day',true]
],['For a three-row frame use 2 PRECEDING AND CURRENT ROW.','For calendar days, generate a complete date spine and join metrics before the window.'],'Three rows are not three days when dates are missing.',[23,35]);
advanced('Share of total with windows',5,'ai','An aggregate window without GROUP BY can put a grand total alongside each group. Aggregate per model first, then use SUM(request_count) OVER() as the denominator.','WITH counts AS(SELECT model,COUNT(*) AS request_count\nFROM ai_requests GROUP BY model)\nSELECT model,request_count,ROUND(100.0*request_count/\nSUM(request_count) OVER(),2) AS share_pct FROM counts;',[
 ['Return model, request_count and share_pct (0–100, 2 decimals) for all request rows by model.','WITH counts AS(SELECT model,COUNT(*) AS request_count FROM ai_requests GROUP BY model) SELECT model,request_count,ROUND(100.0*request_count/SUM(request_count) OVER(),2) AS share_pct FROM counts'],
 ['Return model, output_tokens and share_pct (0–100, 2 decimals) of total successful output tokens by model.','WITH totals AS(SELECT model,SUM(output_tokens) AS output_tokens FROM ai_requests WHERE status=\'success\' GROUP BY model) SELECT model,output_tokens,ROUND(100.0*output_tokens/NULLIF(SUM(output_tokens) OVER(),0),2) AS share_pct FROM totals']
],['Compute one row per model in a CTE.','SUM(...) OVER() returns the grand total without collapsing model rows.'],'Partitioning by model would give each model 100%.',[20,32]);
advanced('Deduplicate event retries',6,'social','Ingestion retries can produce several physical rows for one logical event. Define the event key and which version wins. ROW_NUMBER per event_key, ordered by ingested_at and id descending, keeps the latest version.','WITH ranked AS(SELECT *,ROW_NUMBER() OVER(\n PARTITION BY event_key ORDER BY ingested_at DESC,id DESC\n) AS rn FROM social_events)\nSELECT id,event_key,member_id FROM ranked WHERE rn=1;',[
 ['Return id, event_key and member_id for the latest ingested row of each event_key. Break ingestion ties by highest id.','WITH ranked AS(SELECT *,ROW_NUMBER() OVER(PARTITION BY event_key ORDER BY ingested_at DESC,id DESC) AS rn FROM social_events) SELECT id,event_key,member_id FROM ranked WHERE rn=1'],
 ['After keeping the latest ingested row per event_key (tie: highest id), return event_type and event_count by event_type.','WITH ranked AS(SELECT *,ROW_NUMBER() OVER(PARTITION BY event_key ORDER BY ingested_at DESC,id DESC) AS rn FROM social_events) SELECT event_type,COUNT(*) AS event_count FROM ranked WHERE rn=1 GROUP BY event_type']
],['The partition is the logical event_key, not member_id.','Filter rn=1 before counting events.'],'DISTINCT on all columns cannot remove retries whose id or ingested_at changed.',[25]);
advanced('Daily active users & engagement',6,'stream','DAU counts distinct people with activity on a calendar day, not event rows. Define engagement separately: here it is total seconds divided by active viewers. This result includes observed dates only.','SELECT date(watched_at) AS day,COUNT(DISTINCT viewer_id)\nAS active_viewers FROM watch_events GROUP BY day;',[
 ['Return day (YYYY-MM-DD) and active_viewers (distinct viewers) for every observed watch date.','SELECT date(watched_at) AS day,COUNT(DISTINCT viewer_id) AS active_viewers FROM watch_events GROUP BY day'],
 ['Return day, active_viewers and minutes_per_active_viewer, rounded to 2 decimals, for each observed watch date.','SELECT date(watched_at) AS day,COUNT(DISTINCT viewer_id) AS active_viewers,ROUND(SUM(watch_seconds)/60.0/COUNT(DISTINCT viewer_id),2) AS minutes_per_active_viewer FROM watch_events GROUP BY day']
],['A viewer can have several watch events on the same day.','Use COUNT(DISTINCT viewer_id) and convert seconds to minutes with 60.0.'],'Counting rows inflates activity for viewers who watched more than once.',[10,39]);
const funnelCTE=`WITH views AS(SELECT member_id,MIN(event_at) AS viewed_at FROM social_events WHERE event_type='view' GROUP BY member_id), signups AS(SELECT v.member_id,v.viewed_at,MIN(e.event_at) AS signed_at FROM views v LEFT JOIN social_events e ON e.member_id=v.member_id AND e.event_type='signup' AND e.event_at>=v.viewed_at GROUP BY v.member_id,v.viewed_at), funnel AS(SELECT s.member_id,s.viewed_at,s.signed_at,MIN(e.event_at) AS purchased_at FROM signups s LEFT JOIN social_events e ON e.member_id=s.member_id AND e.event_type='purchase' AND e.event_at>=s.signed_at GROUP BY s.member_id,s.viewed_at,s.signed_at)`;
advanced('Ordered conversion funnels',6,'social','A funnel is an ordered journey. Find the first view, then the first signup on or after that view, then the first purchase on or after signup. A purchase that happens before signup does not complete this funnel. Equal timestamps are allowed here.','-- Build one row per member at each stage.\n'+funnelCTE+'\nSELECT COUNT(*) AS viewed,COUNT(signed_at) AS signed_up,\nCOUNT(purchased_at) AS purchased FROM funnel;',[
 ['Return one row: viewed, signed_up, purchased as member counts for the ordered view → signup → purchase funnel. Equal times are allowed; use each member\'s earliest valid next step.',''+funnelCTE+' SELECT COUNT(*) AS viewed,COUNT(signed_at) AS signed_up,COUNT(purchased_at) AS purchased FROM funnel'],
 ['Return member_id, viewed_at, signed_at and purchased_at for members who complete that ordered funnel.',''+funnelCTE+' SELECT member_id,viewed_at,signed_at,purchased_at FROM funnel WHERE purchased_at IS NOT NULL']
],['Make the next step conditional on the previous step’s timestamp.','Use LEFT JOIN for stage counts so drop-offs remain in the denominator.'],'Counting event types independently ignores sequence and includes invalid journeys.',[20,37]);
function retentionSQL(n){return `SELECT v.signup_at AS cohort_day,COUNT(*) AS cohort_size,SUM(CASE WHEN EXISTS(SELECT 1 FROM watch_events w WHERE w.viewer_id=v.id AND date(w.watched_at)=date(v.signup_at,'+${n} days')) THEN 1 ELSE 0 END) AS retained_viewers,ROUND(100.0*SUM(CASE WHEN EXISTS(SELECT 1 FROM watch_events w WHERE w.viewer_id=v.id AND date(w.watched_at)=date(v.signup_at,'+${n} days')) THEN 1 ELSE 0 END)/COUNT(*),2) AS retention_pct FROM viewers v WHERE v.signup_at<=date('2025-01-15','-${n} days') GROUP BY v.signup_at`;}
advanced('Cohorts & exact-day retention',6,'stream','A cohort groups people by signup date. Exact-day D1 retention asks whether they return on signup +1 day, not anytime later. Count people, include non-returners, and exclude cohorts that have not matured by the observation cutoff.','-- D1 retention; observation cutoff is 2025-01-15\n'+retentionSQL(1),[
 ['With observation cutoff Jan 15 2025, return cohort_day, cohort_size, retained_viewers and retention_pct (0–100, 2 decimals) for exact-day D1 retention. Include only mature cohorts.',''+retentionSQL(1)],
 ['Use the same output and cutoff for exact-day D7 retention (signup date +7 days); include only mature cohorts.',''+retentionSQL(7)]
],['The denominator is all viewers in the mature signup cohort.','Use EXISTS on the exact return date to avoid duplicating viewers.'],'A seven-day window and exact-day D7 retention are different metrics.',[18,39]);
const sessionCTE=`WITH previous AS(SELECT *,LAG(event_at) OVER(PARTITION BY member_id ORDER BY event_at,id) AS previous_at FROM social_events), marked AS(SELECT *,CASE WHEN previous_at IS NULL OR unixepoch(event_at)-unixepoch(previous_at)>=1800 THEN 1 ELSE 0 END AS new_session FROM previous), numbered AS(SELECT *,SUM(new_session) OVER(PARTITION BY member_id ORDER BY event_at,id ROWS UNBOUNDED PRECEDING) AS session_number FROM marked)`;
advanced('Sessionize an event stream',6,'social','A session starts on a member’s first event or after a gap of at least 30 minutes. LAG finds the prior timestamp, CASE flags boundaries, and a running SUM numbers sessions. Here we use physical rows, including retries. Identical timestamps do not start a new session.',''+sessionCTE+'\nSELECT member_id,MAX(session_number) AS session_count\nFROM numbered GROUP BY member_id;',[
 ['Using raw social_events, return member_id and session_count. Start a new session on the first event or a gap of at least 30 minutes; order by event_at then id per member.',''+sessionCTE+' SELECT member_id,MAX(session_number) AS session_count FROM numbered GROUP BY member_id'],
 ['Using the same rule, return id, member_id and session_number for every raw social event.',''+sessionCTE+' SELECT id,member_id,session_number FROM numbered']
],['Use unixepoch differences in seconds to avoid floating date rounding.','Mark gaps >=1800 seconds, then running SUM the markers per member.'],'Strictly greater than 30 minutes is not the same as at least 30 minutes.',[24,23]);
advanced('Multi-grain joins without fan-out',6,'ai','Requests and invoices each have many rows per account. Joining raw tables creates requests × invoices and inflates sums. Aggregate each side to one row per account before joining; keep accounts with zero on either side.','WITH usage AS(SELECT account_id,COUNT(*) AS request_count\nFROM ai_requests GROUP BY account_id), billing AS(\nSELECT account_id,SUM(billed_amount) AS billed_amount\nFROM invoices GROUP BY account_id)\nSELECT a.id,COALESCE(u.request_count,0) AS request_count,\nCOALESCE(b.billed_amount,0) AS billed_amount FROM ai_accounts a\nLEFT JOIN usage u ON u.account_id=a.id\nLEFT JOIN billing b ON b.account_id=a.id;',[
 ['Return id, request_count and billed_amount for every account across all dates. Aggregate requests and invoices separately to avoid multiplication; use zeros for missing totals.','WITH usage AS(SELECT account_id,COUNT(*) AS request_count FROM ai_requests GROUP BY account_id),billing AS(SELECT account_id,SUM(billed_amount) AS billed_amount FROM invoices GROUP BY account_id) SELECT a.id,COALESCE(u.request_count,0) AS request_count,COALESCE(b.billed_amount,0) AS billed_amount FROM ai_accounts a LEFT JOIN usage u ON u.account_id=a.id LEFT JOIN billing b ON b.account_id=a.id'],
 ['Return id, output_tokens and billed_amount for every account across all dates. Sum only successful output tokens and aggregate invoices separately. Use zeros for missing totals.','WITH usage AS(SELECT account_id,SUM(output_tokens) AS output_tokens FROM ai_requests WHERE status=\'success\' GROUP BY account_id),billing AS(SELECT account_id,SUM(billed_amount) AS billed_amount FROM invoices GROUP BY account_id) SELECT a.id,COALESCE(u.output_tokens,0) AS output_tokens,COALESCE(b.billed_amount,0) AS billed_amount FROM ai_accounts a LEFT JOIN usage u ON u.account_id=a.id LEFT JOIN billing b ON b.account_id=a.id']
],['Choose account as the grain for both intermediate tables.','Join the summaries to accounts only after GROUP BY account_id.'],'DISTINCT cannot repair inflated SUM values after a many-to-many join.',[20,16]);
const reconcileCTE=`WITH paid AS(SELECT invoice_id,SUM(amount) AS paid_amount FROM payments GROUP BY invoice_id),returned AS(SELECT invoice_id,SUM(amount) AS refund_amount FROM refunds GROUP BY invoice_id)`;
advanced('Revenue & payment reconciliation',6,'ai','Reconciliation compares independent totals. Sum payments and refunds by invoice before joining. Net collected is payments minus refunds; gap is billed minus net collected. A refund creates a gap under this definition, even when the original bill was paid.',''+reconcileCTE+'\nSELECT i.id,i.billed_amount,\nCOALESCE(p.paid_amount,0)-COALESCE(r.refund_amount,0) AS net_collected,\ni.billed_amount-COALESCE(p.paid_amount,0)+COALESCE(r.refund_amount,0) AS gap\nFROM invoices i LEFT JOIN paid p ON p.invoice_id=i.id\nLEFT JOIN returned r ON r.invoice_id=i.id;',[
 ['Return id, billed_amount, net_collected and gap for every invoice across all periods. Net collected = payments - refunds; gap = billed - net collected. Treat missing totals as zero.',''+reconcileCTE+' SELECT i.id,i.billed_amount,COALESCE(p.paid_amount,0)-COALESCE(r.refund_amount,0) AS net_collected,i.billed_amount-COALESCE(p.paid_amount,0)+COALESCE(r.refund_amount,0) AS gap FROM invoices i LEFT JOIN paid p ON p.invoice_id=i.id LEFT JOIN returned r ON r.invoice_id=i.id'],
 ['Using the same definition, return invoice_id and gap only for invoices with nonzero gap.',''+reconcileCTE+', result AS(SELECT i.id AS invoice_id,i.billed_amount-COALESCE(p.paid_amount,0)+COALESCE(r.refund_amount,0) AS gap FROM invoices i LEFT JOIN paid p ON p.invoice_id=i.id LEFT JOIN returned r ON r.invoice_id=i.id) SELECT invoice_id,gap FROM result WHERE gap<>0']
],['Aggregate the two transaction tables independently.','A split payment combined with two refunds produces four joined rows unless pre-aggregated.'],'Unmatched payments need a separate investigation; they are not assigned to an invoice here.',[49]);
advanced('AI usage cost & contribution margin',6,'ai','Usage cost equals input tokens × input rate plus output tokens × output rate, divided by one million. These rates are fictional. Under this exercise’s rule, successful requests are chargeable; errors are excluded. Compare January billed revenue to January successful usage cost, not all-time billing.','SELECT r.model,ROUND(SUM(r.input_tokens*m.input_per_million+\nr.output_tokens*m.output_per_million)/1000000.0,6) AS usage_cost\nFROM ai_requests r JOIN model_rates m ON m.model=r.model\nWHERE r.status=\'success\' GROUP BY r.model;',[
 ['Return model and usage_cost in fictional USD, rounded to 6 decimals, for successful requests across all dates.','SELECT r.model,ROUND(SUM(r.input_tokens*m.input_per_million+r.output_tokens*m.output_per_million)/1000000.0,6) AS usage_cost FROM ai_requests r JOIN model_rates m ON m.model=r.model WHERE r.status=\'success\' GROUP BY r.model'],
 ['Return id, billed_amount, usage_cost and contribution_margin for every account for Jan 2025. Use January invoices and successful requests only; missing totals are zero. Round cost and margin to 6 decimals. Margin = billed - usage cost.','WITH costs AS(SELECT r.account_id,SUM(r.input_tokens*m.input_per_million+r.output_tokens*m.output_per_million)/1000000.0 AS usage_cost FROM ai_requests r JOIN model_rates m ON m.model=r.model WHERE r.status=\'success\' AND r.requested_at>=\'2025-01-01\' AND r.requested_at<\'2025-02-01\' GROUP BY r.account_id),billing AS(SELECT account_id,SUM(billed_amount) AS billed_amount FROM invoices WHERE period=\'2025-01\' GROUP BY account_id) SELECT a.id,COALESCE(b.billed_amount,0) AS billed_amount,ROUND(COALESCE(c.usage_cost,0),6) AS usage_cost,ROUND(COALESCE(b.billed_amount,0)-COALESCE(c.usage_cost,0),6) AS contribution_margin FROM ai_accounts a LEFT JOIN costs c ON c.account_id=a.id LEFT JOIN billing b ON b.account_id=a.id']
],['Rates are per million; divide after adding input and output charges.','Summarize both usage and billing per account before joining.'],'This simplified contribution margin excludes other costs and refunds; it is not net profit.',[49,32]);
advanced('Experiment conversion denominators',6,'social','Compare assigned members, including people who do nothing. A conversion is at least one purchase on or after assignment, through Jan 31. Counting purchases instead of members or using only active members biases the denominator. This query estimates rates, not statistical significance.','WITH results AS(SELECT a.member_id,a.variant,CASE WHEN EXISTS(\n SELECT 1 FROM social_events e WHERE e.member_id=a.member_id\n AND e.event_type=\'purchase\' AND e.event_at>=a.assigned_at\n AND e.event_at<\'2025-02-01\') THEN 1 ELSE 0 END AS converted\nFROM experiment_assignments a)\nSELECT variant,COUNT(*) AS assigned,SUM(converted) AS converted,\nROUND(100.0*SUM(converted)/COUNT(*),2) AS conversion_pct\nFROM results GROUP BY variant;',[
 ['Return variant, assigned, converted and conversion_pct (0–100, 2 decimals). A member converts with any purchase on/after assigned_at and before Feb 1 2025. Include all assigned members.','WITH results AS(SELECT a.member_id,a.variant,CASE WHEN EXISTS(SELECT 1 FROM social_events e WHERE e.member_id=a.member_id AND e.event_type=\'purchase\' AND e.event_at>=a.assigned_at AND e.event_at<\'2025-02-01\') THEN 1 ELSE 0 END AS converted FROM experiment_assignments a) SELECT variant,COUNT(*) AS assigned,SUM(converted) AS converted,ROUND(100.0*SUM(converted)/COUNT(*),2) AS conversion_pct FROM results GROUP BY variant'],
 ['Return member_id, variant and converted (1 or 0) for every assignment using the same post-assignment purchase definition and cutoff.','SELECT a.member_id,a.variant,CASE WHEN EXISTS(SELECT 1 FROM social_events e WHERE e.member_id=a.member_id AND e.event_type=\'purchase\' AND e.event_at>=a.assigned_at AND e.event_at<\'2025-02-01\') THEN 1 ELSE 0 END AS converted FROM experiment_assignments a']
],['Keep the assignments table as the population.','EXISTS counts a member once regardless of purchase row count.'],'A higher observed conversion rate alone does not establish a significant treatment effect.',[18,32]);
advanced('Top N per group & ties',5,'stream','Aggregate watched seconds per video, then rank videos within creator. ROW_NUMBER gives an exact N with a tie-breaker; DENSE_RANK includes ties and may return more than N. Make the tie policy explicit.','WITH totals AS(SELECT v.creator_id,v.id AS video_id,\nSUM(w.watch_seconds) AS watch_seconds FROM videos v\nJOIN watch_events w ON w.video_id=v.id GROUP BY v.id,v.creator_id),\nranked AS(SELECT *,ROW_NUMBER() OVER(PARTITION BY creator_id\nORDER BY watch_seconds DESC,video_id) AS rn FROM totals)\nSELECT creator_id,video_id,watch_seconds FROM ranked WHERE rn<=2;',[
 ['Return creator_id, video_id and watch_seconds for the top 2 watched videos per creator, excluding videos with no events. Rank by total seconds descending, break ties by smallest video_id.','WITH totals AS(SELECT v.creator_id,v.id AS video_id,SUM(w.watch_seconds) AS watch_seconds FROM videos v JOIN watch_events w ON w.video_id=v.id GROUP BY v.id,v.creator_id),ranked AS(SELECT *,ROW_NUMBER() OVER(PARTITION BY creator_id ORDER BY watch_seconds DESC,video_id) AS rn FROM totals) SELECT creator_id,video_id,watch_seconds FROM ranked WHERE rn<=2'],
 ['Return creator_id, video_id and watch_seconds for each creator\'s most-watched video(s), including ties. Exclude videos with no events.','WITH totals AS(SELECT v.creator_id,v.id AS video_id,SUM(w.watch_seconds) AS watch_seconds FROM videos v JOIN watch_events w ON w.video_id=v.id GROUP BY v.id,v.creator_id),ranked AS(SELECT *,DENSE_RANK() OVER(PARTITION BY creator_id ORDER BY watch_seconds DESC) AS rn FROM totals) SELECT creator_id,video_id,watch_seconds FROM ranked WHERE rn=1']
],['Aggregate per video before ranking within creator.','Use a video_id tie-breaker only when you need an exact number of rows.'],'Adding video_id to a DENSE_RANK ordering eliminates watch-time ties.',[22,25]);
